import { expect, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("REV-02 Vendor"),
      category: "services",
      contact_email: `rev02.${suffix}@vendor-mail.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const uploaded = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: Buffer.from("Legal Name: Acme\nTax ID: 123456789\n"),
      },
    },
  });
  expect(uploaded.status(), await uploaded.text()).toBe(201);
  const document = (await uploaded.json()) as { id: string };

  // Extraction runs in the background; wait until the W-9 is extracted.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return ((await res.json()) as { status: string }).status;
      },
      { message: "w9 extraction finishes" },
    )
    .toBe("extracted");

  // Act
  const response = await member.post(`/api/vendors/${vendor.id}/submit`);

  // Assert
  expect(response.status(), await response.text()).toBe(409);
  const body = (await response.json()) as {
    error: { code: string; missing_kinds: string[] };
  };
  expect(body.error.code, JSON.stringify(body)).toBe("documents_incomplete");
  expect(body.error.missing_kinds, JSON.stringify(body)).toEqual([
    "contract",
    "insurance_certificate",
  ]);
});
